INSERT INTO reviews (source, rating, body, display_mode, display_name, period_label, consent_publish, consent_at, status, sort, created_at)
SELECT 'legacy', NULL, $r$من باب إعطاء كل ذي حق حقه، ابي اعبر لك عن كمية امتناني وشكري لك على عطائك ومبادرتك الدايمه والحرص علي وعلى […] لاني شفت منك حرص مب عند الكل، البعض يتوقع انه اذا دفع لمدرب بيكون هذا العطاء شيء طبيعي لكن التمست منك الحرص والاهتمام وحثك لي ولـ[…] على الالتزام والاهتمام بصحتنا وفوقها صبرك وايثارك للمتدربين على نفسك، حاب اقولك تراك شخص معطاء ولك اثر وفرق على حياتنا مب مجرد شخص عابر ومهما حاولت ابين لك امتناني شكري الا اني افشل في كل مره عن اظهاره، شكرا لك يا اطلق كوتش 🙏$r$, 'anon', 'أحد المتدربين', 'رسالة واتساب', true, now(), 'published', 100, now() - interval '0 seconds'
