INSERT INTO reviews (source, rating, body, display_mode, display_name, period_label, consent_publish, consent_at, status, sort, created_at)
SELECT 'legacy', NULL, $r$يشهد الله اني شفت اهتمام نفسي منك بشكل مب طبيعي واني تعلمت منك باسبوعين اشياء ماتعلمتها قبل خلال شهور، وما شفت ولا اتوقع بشوف احد مثلك يرد صباح وليل وفجر وايام اسبوع وويكند ويبحث ويجتهد، يمكن هالشيء مب واضح من مشتركك للمتواضع لكن ترا هالاهتمام النفسي من الدوافع الاقوى للتمرين، مافيه مدرب بيروح يدخل مراجع ويبحث ويطلع عشان مشترك ساله سؤال ما يعرفه بالعاده بيصرف له اجابه من اقرب موقع قوقل، اتوقع اني اوصل شعور كل مشترينك بإمتنانهن لدعمك النفسي والمتابعه، ف حتى لو ما بان هالشيء ظاهريا ف هو واصل بالباطن 🙏$r$, 'anon', 'أحد المتدربين', 'رسالة من متدرب/ة', true, now(), 'published', 104, now() - interval '4 seconds'
