SELECT 'legacy', NULL, $r$من زمان ودي اكتب لك الكلام ذا. صراحة الي تقدمينه للناس بمجهود بالنادي والمشتركين مره رهيب لأن جربت اكون ضايع قبل بالنادي ولا اعرف وش اسوي وبعض النصائح الي تجيب العيد من المدربين بس عشان يصرفك بس انتي مشاءالله تسوين شغلك بحب وإخلاص وتعدلين لهم المفاهيم وتوضحين الطريق الصحيح ويعني اكبر دليل كلام الناس لك يوضح حبك لمهنة التدريب وشعور جميل انك تساعدين احد بتحسن لحياته وجسمه يدوره من وقت متأكد اسعدتي ناس كثير والله يكتب لك الاجر. لو افكر بيوم ارجع للنادي بيكون تحت ارشادك، الله يوفقك ويقويك على فعل الخير ويسعدك مثل ما اسعدتي الناس$r$, 'anon', 'أحد المتدربين', 'رسالة من متدرب/ة', true, now(), 'published', 112, now() - interval '12 seconds'
WHERE NOT EXISTS (SELECT 1 FROM reviews WHERE body = $r$من زمان ودي اكتب لك الكلام ذا. صراحة الي تقدمينه للناس بمجهود بالنادي والمشتركين مره رهيب لأن جربت اكون ضايع قبل بالنادي ولا اعرف وش اسوي وبعض النصائح الي تجيب العيد من المدربين بس عشان يصرفك بس انتي مشاءالله تسوين شغلك بحب وإخلاص وتعدلين لهم المفاهيم وتوضحين الطريق الصحيح ويعني اكبر دليل كلام الناس لك يوضح حبك لمهنة التدريب وشعور جميل انك تساعدين احد بتحسن لحياته وجسمه يدوره من وقت متأكد اسعدتي ناس كثير والله يكتب لك الاجر. لو افكر بيوم ارجع للنادي بيكون تحت ارشادك، الله يوفقك ويقويك على فعل الخير ويسعدك مثل ما اسعدتي الناس$r$);
